# ---- helpers ------------------------------------------------------------------
def _eq(a, b, tag):
    assert a == b, "%s: %r != %r" % (tag, a, b)


def _bits(x):
    return (repr(x), math.copysign(1.0, x))


def _deep(a, b, tag):
    if isinstance(a, dict) and isinstance(b, dict):
        _eq(sorted(a.keys()), sorted(b.keys()), tag + ".keys")
        for k in a:
            _deep(a[k], b[k], tag + "." + str(k))
    elif isinstance(a, list) and isinstance(b, list):
        _eq(len(a), len(b), tag + ".len")
        for i, (x, y) in enumerate(zip(a, b)):
            _deep(x, y, "%s[%d]" % (tag, i))
    elif isinstance(a, float) or isinstance(b, float):
        _eq(_bits(a), _bits(b), tag + ".bits")
    else:
        _eq(a, b, tag)


def C(solve, mode, **kw):
    return solve(mode, **kw)


def _exc(fn):
    try:
        fn()
        return None
    except Exception as e:
        return {"type": type(e).__name__, "msg": str(e)}


def _flat(x):
    if isinstance(x, list):
        out = []
        for v in x:
            out.extend(_flat(v))
        return out
    return [x]


# ---- census / structure --------------------------------------------------------
def check_census_matches(solve):
    _deep(C(solve, "census"), CENSUS870, "census")


def check_census_fresh_dict(solve):
    a = C(solve, "census")
    b = C(solve, "census")
    assert a is not b, "census must return a fresh dict"
    assert a["top_level"] is not b["top_level"], "top_level must be fresh"
    assert a["funcs"] is not b["funcs"], "funcs must be fresh"
    assert a["consts"] is not b["consts"], "consts must be fresh"
    assert a["modes"] is not b["modes"], "modes must be fresh"
    a["top_level"].append([0, "MUTATED"])
    a["consts"]["up_scaling"] = -1
    _eq(len(b["top_level"]), 30, "census.top_level.immutable")
    _eq(b["consts"]["up_scaling"], 32766, "census.consts.immutable")


def check_unknown_mode(solve):
    e = _exc(lambda: C(solve, "no_such_mode"))
    assert e is not None, "unknown mode must raise"
    _eq(e["type"], "ValueError", "unknown.type")
    assert "unknown mode" in e["msg"], "unknown.msg"
    for m in MODES870:
        assert isinstance(C(solve, m), dict), "mode %s must return dict" % m


def check_scales(solve):
    s = SCALES870
    _eq(s["number_of_bits"], 16, "scales.bits")
    _eq(s["up_scaling"], 2 ** 15 - 2, "scales.up")
    _eq(s["down_scaling"], 2 ** 15, "scales.down")
    _eq(s["num_rand_variables"], 6, "scales.n")
    _eq(CENSUS870["consts"], s, "scales.census")


# ---- Bartlett window -----------------------------------------------------------
def check_bartlett_n1(solve):
    _deep(C(solve, "bartlett", n=1), BARTLETT_N1, "bartlett.n1")
    _eq(BARTLETT_N1["window"], [1.0], "bartlett.n1.value")


def check_bartlett_grid(solve):
    for n in range(1, 25):
        want = globals()["BARTLETT_%d" % n]
        _deep(C(solve, "bartlett", n=n)["window"], want, "bartlett.n%d" % n)


def check_bartlett_float_asymmetry(solve):
    for key, want in BARTLETT_ASYM.items():
        _deep(C(solve, "bartlett", n=int(key))["window"], want,
              "bartlett.asym.%s" % key)
    w5 = BARTLETT_5
    _eq(_bits(w5[2]), _bits(0.8), "bartlett.asym5.left")
    _eq(_bits(w5[3]), _bits(0.7999999999999998), "bartlett.asym5.right")
    assert w5[2] != w5[3], "bartlett float halves must NOT be symmetric for n=5"
    assert BARTLETT_6[1] == 0.3333333333333333, "bartlett n=6 left float"


def check_bartlett_endpoints(solve):
    for n in range(2, 25):
        w = globals()["BARTLETT_%d" % n]
        _eq(w[0], 0.0, "bartlett.endpoint.n%d" % n)
        assert all(x >= 0.0 for x in w), "bartlett.nonneg.n%d" % n
        assert max(w) <= 1.0, "bartlett.peak.n%d" % n


