# ---- GPDF ----------------------------------------------------------------------
def check_gpdf_alias_doubling(solve):
    r = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="GPDF", rng=[0] * 14)
    _deep(r, QUANT_GPDF_ALLZERO_DOUBLING, "gpdf.doubling")
    hand = round(0.1 * 32766 + 0.1 * (2 ** 6)) / 32768
    _eq(_bits(r["out"][0][0]), _bits(hand), "gpdf.doubling.hand")
    _eq(0.1 * (2 ** 6), 6.4, "gpdf.doubling.64")


def check_gpdf_rng_grid(solve):
    for sk in ("S0", "S1", "S2", "S3"):
        got = C(solve, "quantize", waveform=WAVES870["W0"],
                density_function="GPDF", rng=RNGS870[sk])
        _deep(got, globals()["QUANT_GPDF_W0_%s" % sk], "gpdf.%s" % sk)
    _deep(C(solve, "quantize", waveform=WAVES870["W8"],
            density_function="GPDF", rng=RNGS870["S0"]),
          QUANT_GPDF_W8_S0, "gpdf.w8")


def check_gpdf_14_calls(solve):
    for sk in ("S0", "S1", "S2", "S3"):
        r = C(solve, "quantize", waveform=WAVES870["W0"],
              density_function="GPDF", rng=RNGS870[sk])
        _eq(len(r["rng_calls"]), 14, "gpdf.calls.%s" % sk)


def check_gpdf_high_pattern(solve):
    r = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="GPDF", rng=RNGS870["S0"])
    _eq([x["high"] for x in r["rng_calls"]], [1, 2] * 7, "gpdf.highs")
    for x in r["rng_calls"]:
        _eq(x["size"], [1], "gpdf.size")


def check_gpdf_differs_from_both(solve):
    a = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="GPDF", rng=RNGS870["S0"])["out"]
    b = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="RPDF", rng=RNGS870["S0"])["out"]
    c = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="TPDF", rng=RNGS870["S0"])["out"]
    assert a != b and a != c and b != c, "three density branches must differ"


