# ---- noise shaping -------------------------------------------------------------
def check_noise_shaping_standalone(solve):
    for tag, (wave, dith) in NS_CASES.items():
        got = C(solve, "noise_shaping", waveform=wave, dithered=dith)
        _deep(got, globals()["NS_%s" % tag], "ns.%s" % tag)


def check_noise_shaping_first_sample(solve):
    for tag, (wave, dith) in NS_CASES.items():
        got = C(solve, "noise_shaping", waveform=wave, dithered=dith)
        for r, d in zip(got["out"], dith):
            _eq(_bits(r[0]), _bits(d[0]), "ns.first.%s" % tag)


def check_noise_shaping_error_field(solve):
    wave, dith = NS_CASES["N0"]
    got = C(solve, "noise_shaping", waveform=wave, dithered=dith)
    for r, w, d in zip(got["error"], wave, dith):
        for a, b, c in zip(r, w, d):
            _eq(_bits(a), _bits(c - b), "ns.error")
    _eq(got["waveform_shape"], [2, 3], "ns.wshape")
    _eq(got["dithered_shape"], [2, 3], "ns.dshape")


def check_dither_ns_equals_standalone(solve):
    q = C(solve, "quantize", waveform=WAVES870["W0"], rng=RNGS870["S0"])
    ns = C(solve, "noise_shaping", waveform=WAVES870["W0"], dithered=q["out"])
    got = C(solve, "quantize", waveform=WAVES870["W0"], rng=RNGS870["S0"],
            noise_shaping=True)
    _deep(got["out"], ns["out"], "ns.equals")
    _deep(got, QUANT_TPDF_NS_W0, "ns.fixture")


def check_gpdf_ns_pollution(solve):
    """GPDF mutates the waveform in place; noise_shaping then sees the grown cell."""
    for sk in ("S0", "S1", "S2", "S3"):
        got = C(solve, "quantize", waveform=WAVES870["W0"],
                density_function="GPDF", rng=RNGS870[sk], noise_shaping=True)
        _deep(got, globals()["QUANT_GPDF_NS_W0_%s" % sk], "gpdf.ns.%s" % sk)
    _deep(C(solve, "quantize", waveform=WAVES870["W8"],
            density_function="GPDF", rng=RNGS870["S0"], noise_shaping=True),
          QUANT_GPDF_NS_W8_S0, "gpdf.ns.w8")


def check_gpdf_ns_differs_from_plain_ns(solve):
    q = C(solve, "quantize", waveform=WAVES870["W0"],
          density_function="GPDF", rng=RNGS870["S0"])["out"]
    plain = C(solve, "noise_shaping", waveform=WAVES870["W0"], dithered=q)["out"]
    polluted = QUANT_GPDF_NS_W0_S0["out"]
    assert plain != polluted, "GPDF noise_shaping must see the mutated waveform"
    assert abs(_flat(polluted)[1]) > 1.0, "mutation must produce a large error"


