# ---- numeric properties --------------------------------------------------------
def check_lattice_integer(solve):
    for i, out in enumerate(LATTICE_SAMPLES):
        for j, x in enumerate(_flat(out)):
            v = x * 32768
            assert v == math.floor(v), "lattice[%d][%d]: %r" % (i, j, x)


def check_quantization_error_bound(solve):
    r = C(solve, "quantize", waveform=WAVES870["W0"], rng=RNGS870["S0"])
    for row, wrow in zip(r["out"], WAVES870["W0"]):
        for x, w in zip(row, wrow):
            assert abs(x * 32768 - w * 32766) <= 1.5 + 1e-9, \
                "quant.error.bound: %r" % x


def check_all_modes_dispatch(solve):
    for m in MODES870:
        r = C(solve, m)
        assert isinstance(r, dict), "mode %s dict" % m
        assert "type" not in r, "mode %s must not be an error dict" % m


