def check_nonfinite_quantize(solve):
    wf = [[float("inf"), float("-inf"), float("nan")], [0.1, 0.2, 0.3]]
    _deep(C(solve, "quantize", waveform=wf, rng=RNGS870["S0"]),
          NONFINITE_QUANT, "nonfinite.quantize")


def check_nonfinite_round(solve):
    vals = [float("inf"), float("-inf"), float("nan"), 0.5, -0.0]
    _deep(C(solve, "round", values=vals), NONFINITE_ROUND, "nonfinite.round")


def check_nonfinite_noise_shaping(solve):
    dith = [[float("inf"), 0.25, 0.3], [float("-inf"), 0.5, float("nan")]]
    _deep(C(solve, "noise_shaping", waveform=WAVES870["W0"], dithered=dith),
          NONFINITE_NS, "nonfinite.noise_shaping")


def check_nested_empty(solve):
    got = _exc(lambda: C(solve, "quantize", waveform=[[]], rng=RNGS870["S0"]))
    _deep(got, NESTED_EMPTY_EXC, "nested.empty")
    _eq(got["type"], "RuntimeError", "nested.empty.type")
    _deep(C(solve, "shapes", shapes=[("nested", [[]])]),
          SHAPES_NESTED_EMPTY, "nested.empty.shapes")


def check_bartlett_large_n_asymmetry(solve):
    """n//2 vs (n-1)//2 differs by 1 ulp at large even n (98 / 196)."""
    for key, want in BARTLETT_LARGE.items():
        _deep(C(solve, "bartlett", n=int(key))["window"], want,
              "bartlett.large.%s" % key)
    _eq(_bits(C(solve, "bartlett", n=98)["window"][49]),
        _bits(BARTLETT_LARGE["98"][49]), "bartlett.large98.peak")


def check_all_defaults_match(solve):
    _deep(C(solve, "bartlett"), DEFAULT_BARTLETT, "defaults.bartlett")
    _deep(C(solve, "round"), DEFAULT_ROUND, "defaults.round")
    _deep(C(solve, "noise_shaping"), DEFAULT_NS, "defaults.noise_shaping")
    _deep(C(solve, "branches"), DEFAULT_BRANCHES, "defaults.branches")
    _deep(C(solve, "quantize"), DEFAULT_QUANTIZE, "defaults.quantize")
    _deep(C(solve, "shapes"), DEFAULT_SHAPES, "defaults.shapes")
    _deep(C(solve, "errors"), DEFAULT_ERRORS, "defaults.errors")
    _deep(C(solve, "census"), CENSUS870, "defaults.census")
